/bin/bash -lc "python - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB'))
g=im.mean(2)
for th in [10,20,30,40,50,60,70,80,100,120,140,160]:
 m=g<th
 print('\\nth',th,'n',m.sum(),'bbox',np.where(m)[1].min(),np.where(m)[1].max(),np.where(m)[0].min(),np.where(m)[0].max())
 for y in range(0,80,4):
  xs=np.where(m[y])[0]
  # runs >=2
  runs=[]
  if len(xs):
   a=p=xs[0]
   for x in xs[1:]:
    if x>p+1:
     if p-a>=1:runs.append((a,p))
     a=x
    p=x
   if p-a>=1:runs.append((a,p))
  print(y,runs[:6])
PY"
